1	import { create } from "zustand";
2	import { FriendService } from "@/services/FriendService";
3	import { Friend, UserSearchResult } from "@/types/friend";
4	
5	interface FriendState {
6	  friends: Friend[];
7	  incoming: Friend[];
8	  outgoing: Friend[];
9	  loading: boolean;
10	  /** Refresh accepted friends, including their protected profile-image URLs. */
11	  loadFriends: () => Promise<void>;
12	  /** Lightweight refresh of just the incoming-request count (for the badge). */
13	  loadIncoming: () => Promise<void>;
14	  /** Full refresh of friends + pending requests (for the dialog). */
15	  loadAll: () => Promise<void>;
16	  search: (q: string) => Promise<UserSearchResult[]>;
17	  sendRequest: (username: string) => Promise<void>;
18	  accept: (userId: string) => Promise<void>;
19	  decline: (userId: string) => Promise<void>;
20	  remove: (userId: string) => Promise<void>;
21	  block: (userId: string) => Promise<void>;
22	  unblock: (userId: string) => Promise<void>;
23	  clear: () => void;
24	}
25	
26	export const useFriendStore = create<FriendState>((set, get) => ({
27	  friends: [],
28	  incoming: [],
29	  outgoing: [],
30	  loading: false,
31	
32	  loadFriends: async () => {
33	    const friends = await FriendService.listFriends();
34	    set({ friends });
35	  },
36	
37	  loadIncoming: async () => {
38	    const incoming = await FriendService.listIncoming();
39	    set({ incoming });
40	  },
41	
42	  loadAll: async () => {
43	    set({ loading: true });
44	    try {
45	      const [friends, incoming, outgoing] = await Promise.all([
46	        FriendService.listFriends(),
47	        FriendService.listIncoming(),
48	        FriendService.listOutgoing(),
49	      ]);
50	      set({ friends, incoming, outgoing });
51	    } finally {
52	      set({ loading: false });
53	    }
54	  },
55	
56	  search: (q) => FriendService.search(q),
57	
58	  sendRequest: async (username) => {
59	    await FriendService.sendRequest(username);
60	    await get().loadAll();
61	  },
62	
63	  accept: async (userId) => {
64	    await FriendService.accept(userId);
65	    await get().loadAll();
66	  },
67	
68	  decline: async (userId) => {
69	    await FriendService.decline(userId);
70	    await get().loadAll();
71	  },
72	
73	  remove: async (userId) => {
74	    await FriendService.remove(userId);
75	    await get().loadAll();
76	  },
77	
78	  block: async (userId) => {
79	    await FriendService.block(userId);
80	    await get().loadAll();
81	  },
82	
83	  unblock: async (userId) => {
84	    await FriendService.unblock(userId);
85	    await get().loadAll();
86	  },
87	
88	  clear: () => set({ friends: [], incoming: [], outgoing: [] }),
89	}));
90	
91	/** Reactive selector for the incoming-request badge count. */
92	export const useIncomingFriendCount = (): number =>
93	  useFriendStore((s) => s.incoming.length);
