4	/** Thin HTTP client for the friends API. Stores call these; components don't. */
5	export const FriendService = {
6	  listFriends(): Promise<Friend[]> {
7	    return api.get<Friend[]>("/friends");
8	  },
9	
10	  listIncoming(): Promise<Friend[]> {
11	    return api.get<Friend[]>("/friends/incoming");
12	  },
13	
14	  listOutgoing(): Promise<Friend[]> {
15	    return api.get<Friend[]>("/friends/outgoing");
16	  },
17	
18	  search(q: string): Promise<UserSearchResult[]> {
19	    return api.get<UserSearchResult[]>("/friends/search", { q });
20	  },
21	
22	  sendRequest(username: string): Promise<Friend> {
23	    return api.post<Friend>("/friends/requests", { username });
24	  },
25	
26	  accept(userId: string): Promise<Friend> {
27	    return api.post<Friend>(`/friends/${userId}/accept`, {});
28	  },
29	
30	  decline(userId: string): Promise<void> {
31	    return api.post<void>(`/friends/${userId}/decline`, {});
32	  },
33	
34	  remove(userId: string): Promise<void> {
35	    return api.del<void>(`/friends/${userId}`);
36	  },
37	
38	  block(userId: string): Promise<void> {
39	    return api.post<void>(`/friends/${userId}/block`, {});
40	  },
41	
42	  unblock(userId: string): Promise<void> {
43	    return api.del<void>(`/friends/${userId}/block`);
44	  },
45	};
